function render(root, props, fire) {
  var weeks = (props.weeks || []).filter(function (w) { return w && w.week != null && w.week !== ''; });
  var unit = props.unit == null ? '$' : props.unit;
  var open = +props.openingBalance || 0, min = +props.minimumCash || 0;
  var sel = props.selected || '';
  function cs(n) { return getComputedStyle(root).getPropertyValue(n).trim() || '#888'; }
  function fmt(v) {
    var a = Math.abs(v), s = v < 0 ? '-' : '';
    if (a >= 1e6) return s + unit + (a / 1e6).toFixed(2) + 'M';
    if (a >= 1e3) return s + unit + Math.round(a / 1e3) + 'K';
    return s + unit + Math.round(a);
  }
  root.querySelector('.title').textContent = props.title || '';
  var bal = [], b = open;
  weeks.forEach(function (w) { b += (+w.inflow || 0) - (+w.outflow || 0); bal.push(b); });
  var endEl = root.querySelector('.end'), lowEl = root.querySelector('.low'), lowLabel = root.querySelector('.low-label');
  var plot = root.querySelector('.plot'), tip = root.querySelector('.tip'), legend = root.querySelector('.legend');
  if (!weeks.length) {
    endEl.textContent = ''; lowEl.textContent = ''; lowLabel.textContent = ''; legend.innerHTML = '';
    plot.innerHTML = '<div style="padding:30px 0;text-align:center;color:' + cs('--muted') + '">No forecast</div>';
    return;
  }
  var li = 0; bal.forEach(function (v, i) { if (v < bal[li]) li = i; });
  endEl.textContent = fmt(bal[bal.length - 1]);
  lowLabel.textContent = 'Lowest · ' + weeks[li].week;
  lowEl.textContent = fmt(bal[li]);
  lowEl.classList.toggle('bad', bal[li] < min);

  var pos = cs('--positive'), neg = cs('--negative'), acc = cs('--accent'), mut = cs('--muted'), bor = cs('--border'), win = cs('--window'), txt = cs('--text');
  var r = plot.getBoundingClientRect(), W = Math.max(300, r.width || 600), H = Math.max(90, r.height || 200);
  var L = 46, R = 46, T = 6, B = 18, pw = W - L - R, ph = H - T - B, n = weeks.length, step = pw / n;
  var mi = 0, mo = 0;
  weeks.forEach(function (w) { mi = Math.max(mi, +w.inflow || 0); mo = Math.max(mo, +w.outflow || 0); });
  var pHi = (mi || 1) * 1.12, pLo = -(mo || 1) * 1.12;
  var py = function (v) { return T + (pHi - v) * ph / (pHi - pLo); };
  var bLo = Math.min(min, Math.min.apply(null, bal), open), bHi = Math.max(min, Math.max.apply(null, bal), open);
  var bs = (bHi - bLo) || 1; bLo -= bs * 0.1; bHi += bs * 0.1;
  var by = function (v) { return T + (bHi - v) * ph / (bHi - bLo); };
  var x = function (i) { return L + step * (i + 0.5); };
  var f = function (v) { return v.toFixed(1); };
  var s = '';
  for (var g = 0; g <= 4; g++) {
    var pv = pLo + (pHi - pLo) * g / 4, yy = py(pv), bv = bLo + (bHi - bLo) * g / 4;
    s += '<line x1="' + L + '" x2="' + (W - R) + '" y1="' + f(yy) + '" y2="' + f(yy) + '" stroke="' + bor + '"/>' +
      '<text x="' + (L - 6) + '" y="' + f(yy + 4) + '" text-anchor="end" fill="' + mut + '" font-size="11">' + fmt(pv) + '</text>' +
      '<text x="' + (W - R + 6) + '" y="' + f(yy + 4) + '" fill="' + mut + '" font-size="11">' + fmt(bv) + '</text>';
  }
  s += '<line x1="' + L + '" x2="' + (W - R) + '" y1="' + f(py(0)) + '" y2="' + f(py(0)) + '" stroke="' + mut + '" stroke-width="1.2"/>';
  var cw = Math.min(26, step * 0.5);
  weeks.forEach(function (w, i) {
    var below = bal[i] < min, isSel = w.week === sel;
    s += '<rect data-i="' + i + '" x="' + f(L + step * i) + '" y="' + T + '" width="' + f(step) + '" height="' + f(ph) + '" rx="4" fill="' +
      (below ? neg : isSel ? acc : 'transparent') + '" fill-opacity="' + (below ? (isSel ? .2 : .1) : isSel ? .12 : 0) + '" style="cursor:pointer"/>';
    var hi = ((+w.inflow || 0)) / pHi * 0 + py(+w.inflow || 0), ho = py(-(+w.outflow || 0));
    s += '<rect x="' + f(x(i) - cw / 2) + '" y="' + f(hi) + '" width="' + f(cw) + '" height="' + f(py(0) - hi) + '" rx="2" fill="' + pos + '" fill-opacity=".75" pointer-events="none"/>' +
      '<rect x="' + f(x(i) - cw / 2) + '" y="' + f(py(0)) + '" width="' + f(cw) + '" height="' + f(ho - py(0)) + '" rx="2" fill="' + neg + '" fill-opacity=".75" pointer-events="none"/>';
  });
  s += '<line x1="' + L + '" x2="' + (W - R) + '" y1="' + f(by(min)) + '" y2="' + f(by(min)) + '" stroke="' + neg + '" stroke-width="1.5" stroke-dasharray="5 4" pointer-events="none"/>';
  var path = function (fn) { return weeks.map(function (w, i) { return (i ? 'L' : 'M') + f(x(i)) + ' ' + f(fn(w, i)); }).join(' '); };
  s += '<path d="' + path(function (w) { return py((+w.inflow || 0) - (+w.outflow || 0)); }) + '" fill="none" stroke="' + txt + '" stroke-width="1.6" stroke-linejoin="round" pointer-events="none"/>';
  s += '<path d="M' + f(L) + ' ' + f(by(open)) + ' ' + path(function (w, i) { return by(bal[i]); }).replace(/^M/, 'L') + '" fill="none" stroke="' + acc + '" stroke-width="2.4" stroke-linejoin="round" pointer-events="none"/>';
  var every = step < 34 ? 2 : 1;
  weeks.forEach(function (w, i) {
    var net = (+w.inflow || 0) - (+w.outflow || 0);
    s += '<circle cx="' + f(x(i)) + '" cy="' + f(py(net)) + '" r="2.6" fill="' + win + '" stroke="' + txt + '" stroke-width="1.5" pointer-events="none"/>' +
      '<circle cx="' + f(x(i)) + '" cy="' + f(by(bal[i])) + '" r="' + (w.week === sel ? 5 : 3.2) + '" fill="' + (bal[i] < min ? neg : win) + '" stroke="' + (bal[i] < min ? neg : acc) + '" stroke-width="2" pointer-events="none"/>';
    if (i % every === 0 || w.week === sel)
      s += '<text x="' + f(x(i)) + '" y="' + (H - 4) + '" text-anchor="middle" fill="' + mut + '" font-size="11" pointer-events="none">' + w.week + '</text>';
  });
  plot.innerHTML = '<svg width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '">' + s + '</svg>';
  legend.innerHTML =
    '<span><i style="width:9px;height:9px;border-radius:2px;background:' + pos + '"></i>Inflow</span>' +
    '<span><i style="width:9px;height:9px;border-radius:2px;background:' + neg + '"></i>Outflow</span>' +
    '<span><i style="width:14px;border-top:1.6px solid ' + txt + '"></i>Net</span>' +
    '<span><i style="width:14px;border-top:2.4px solid ' + acc + '"></i>Cash balance</span>' +
    '<span><i style="width:14px;border-top:1.5px dashed ' + neg + '"></i>Minimum cash ' + fmt(min) + '</span>';
  plot.querySelectorAll('rect[data-i]').forEach(function (el) {
    var i = +el.getAttribute('data-i'), w = weeks[i];
    el.addEventListener('click', function () { fire('weekSelected', { week: String(w.week), selected: String(w.week) }); });
    el.addEventListener('mouseenter', function () {
      var net = (+w.inflow || 0) - (+w.outflow || 0);
      var row = function (a, v) { return '<div class="r"><span>' + a + '</span><b>' + v + '</b></div>'; };
      tip.innerHTML = '<div style="font-weight:600;margin-bottom:3px;color:' + txt + '">' + w.week + '</div>' + row('Inflow', fmt(+w.inflow || 0)) + row('Outflow', fmt(+w.outflow || 0)) + row('Net', fmt(net)) + row('Balance', fmt(bal[i]));
      tip.style.display = 'block';
      var tw = tip.offsetWidth, th = tip.offsetHeight, tx = x(i) + 12;
      if (tx + tw > W) tx = x(i) - 12 - tw;
      tip.style.left = Math.max(0, tx) + 'px';
      tip.style.top = Math.max(0, Math.min(H - th, by(bal[i]) - th / 2)) + 'px';
    });
    el.addEventListener('mouseleave', function () { tip.style.display = 'none'; });
  });
}
